var name = external_exports.string().trim().min(2).max(150);
var email3 = external_exports.string().trim().email().max(255);
var text = external_exports.string().max(200).optional();
var member = external_exports.object({ nome: name, email: email3, role: external_exports.enum(["admin", "dentista", "recepcionista", "auxiliar", "financeiro"]) });
var professional = external_exports.object({ nome: name, cro_numero: text, especialidade: external_exports.string().max(100).optional() });
var procedure = external_exports.object({ nome: name, codigo_tuss: text, valor: external_exports.coerce.number().min(0).max(1e6), duracao_minutos: external_exports.coerce.number().int().min(10).max(480) });
var schema2 = external_exports.object({ nome: name, slug: external_exports.string().regex(/^[a-z0-9-]{2,80}$/).optional(), cro_responsavel: text, telefone: text, cor_primaria: external_exports.string().regex(/^#[0-9a-f]{6}$/i).optional(), endereco: external_exports.record(external_exports.string(), external_exports.string().max(200)).optional(), membros: external_exports.array(member).max(30).default([]), profissionais: external_exports.array(professional).max(30).default([]), procedimentos: external_exports.array(procedure).max(100).default([]) });
var insert = (table, data) => ({ sql: "INSERT INTO " + table + " (" + Object.keys(data).join(",") + ") VALUES (" + Object.keys(data).map(() => "?").join(",") + ")", args: Object.values(data).map((v) => v !== null && typeof v === "object" ? JSON.stringify(v) : v ?? null) });
async function createClinic(ctx, input2, master = false) {
  if (!ctx.identity.userId) throw Error("Autentica\xE7\xE3o necess\xE1ria");
  if (master && !ctx.identity.master) throw Error("Apenas o administrador da plataforma pode cadastrar cl\xEDnicas");
  if (!master && ctx.identity.clinicaId) return { id: ctx.identity.clinicaId };
  const ownerEmail = master ? email3.parse(input2.email_admin).toLowerCase() : ctx.identity.email;
  const ownerName = master ? name.parse(input2.nome_admin) : String(input2.nome_admin || ctx.identity.email).slice(0, 150);
  const d = schema2.parse({ ...input2, slug: input2.slug || void 0, cor_primaria: input2.cor_primaria || input2.cor_principal, cro_responsavel: input2.cro_responsavel || input2.cro_clinica, membros: (input2.membros || []).filter((m) => m.email), profissionais: (input2.profissionais || []).filter((p) => p.nome), procedimentos: (input2.procedimentos || []).filter((p) => p.nome) });
  const id = crypto.randomUUID(), slug = d.slug || d.nome.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "").slice(0, 60) + "-" + id.slice(0, 8);
  const plano = master ? external_exports.enum(["starter", "pro", "premium"]).default("starter").parse(input2.plano) : "starter";
  const amount = master ? external_exports.coerce.number().min(0).max(99999).default(0).parse(input2.valor_mensal) : 0;
  const ops = [insert("clinica", { id, nome: d.nome, slug, telefone: d.telefone, cor_primaria: d.cor_primaria || "#06B6D4", cro_responsavel: d.cro_responsavel, endereco: d.endereco || {}, owner_email: ownerEmail, owner_nome: ownerName, plano, valor_mensal: amount, mrr: amount, status: "trial", status_cobranca: "ativo", trial_ate: new Date(Date.now() + 14 * 864e5).toISOString().slice(0, 10) }), insert("membro_equipe", { id: crypto.randomUUID(), clinica_id: id, nome: ownerName, email: ownerEmail, role: "owner", user_id: ownerEmail === ctx.identity.email ? ctx.identity.userId : null })];
  for (const m of d.membros) ops.push(insert("membro_equipe", { ...m, email: m.email.toLowerCase(), id: crypto.randomUUID(), clinica_id: id }));
  for (const p of d.profissionais) ops.push(insert("profissional", { ...p, id: crypto.randomUUID(), clinica_id: id }));
  for (const p of d.procedimentos) ops.push(insert("procedimento", { ...p, id: crypto.randomUUID(), clinica_id: id }));
  await ctx.sql.batch(ops, "write");
  return { id, slug, clinica: d.nome, email: ownerEmail, nome_admin: ownerName, telefone: d.telefone };
}

